import 'package:sign_in_with_apple/sign_in_with_apple.dart';

class AppleAuthService {
  final FirebaseAuth _auth = FirebaseAuth.instance;

  Future<UserCredential> signInWithApple() async {
    // Apple 인증 요청
    final appleCredential = await SignInWithApple.getAppleIDCredential(
      scopes: [
        AppleIDAuthorizationScopes.email,
        AppleIDAuthorizationScopes.fullName,
      ],
    );

    // Firebase credential 생성
    final oauthCredential = OAuthProvider('apple.com').credential(
      idToken: appleCredential.identityToken,
      accessToken: appleCredential.authorizationCode,
    );

    // Firebase에 로그인
    return await _auth.signInWithCredential(oauthCredential);
  }
}

import 'package:firebase_auth/firebase_auth.dart';

class PhoneAuthService {
  final FirebaseAuth _auth = FirebaseAuth.instance;
  String? _verificationId;

  // 인증번호 발송
  Future<void> sendVerificationCode({
    required String phoneNumber,
    required Function(String) onCodeSent,
    required Function(String) onError,
    required Function(UserCredential) onAutoVerified,
  }) async {
    await _auth.verifyPhoneNumber(
      phoneNumber: phoneNumber, // +821012345678 형식
      timeout: const Duration(seconds: 60),

      // 인증번호 발송됨
      codeSent: (verificationId, resendToken) {
        _verificationId = verificationId;
        onCodeSent('인증번호가 발송되었습니다.');
      },

      // 자동 인증 완료 (Android)
      verificationCompleted: (credential) async {
        final userCredential = await _auth.signInWithCredential(credential);
        onAutoVerified(userCredential);
      },

      // 인증 실패
      verificationFailed: (exception) {
        String message;
        switch (exception.code) {
          case 'invalid-phone-number':
            message = '유효하지 않은 전화번호입니다.';
            break;
          case 'too-many-requests':
            message = '너무 많은 요청입니다. 잠시 후 다시 시도하세요.';
            break;
          default:
            message = exception.message ?? '인증 오류가 발생했습니다.';
        }
        onError(message);
      },

      // 자동 인증 타임아웃
      codeAutoRetrievalTimeout: (verificationId) {
        _verificationId = verificationId;
      },
    );
  }

  // 인증번호 확인
  Future<UserCredential> verifyCode(String smsCode) async {
    if (_verificationId == null) {
      throw '인증을 먼저 요청해주세요.';
    }

    final credential = PhoneAuthProvider.credential(
      verificationId: _verificationId!,
      smsCode: smsCode,
    );

    return await _auth.signInWithCredential(credential);
  }

  // 기존 계정에 전화번호 연결
  Future<void> linkPhoneNumber(String smsCode) async {
    if (_verificationId == null || _auth.currentUser == null) {
      throw '인증 정보가 없습니다.';
    }

    final credential = PhoneAuthProvider.credential(
      verificationId: _verificationId!,
      smsCode: smsCode,
    );

    await _auth.currentUser!.linkWithCredential(credential);
  }
}

import 'package:flutter/material.dart';
import 'package:firebase_auth/firebase_auth.dart';

// 인증 래퍼
class AuthWrapper extends StatelessWidget {
  const AuthWrapper({super.key});

  @override
  Widget build(BuildContext context) {
    return StreamBuilder<User?>(
      stream: FirebaseAuth.instance.authStateChanges(),
      builder: (context, snapshot) {
        // 로딩 중
        if (snapshot.connectionState == ConnectionState.waiting) {
          return const Scaffold(
            body: Center(child: CircularProgressIndicator()),
          );
        }

        // 로그인됨
        if (snapshot.hasData) {
          return HomeScreen(user: snapshot.data!);
        }

        // 로그인 안됨
        return const LoginScreen();
      },
    );
  }
}

// 로그인 화면
class LoginScreen extends StatefulWidget {
  const LoginScreen({super.key});

  @override
  State<LoginScreen> createState() => _LoginScreenState();
}

class _LoginScreenState extends State<LoginScreen> {
  final _auth = FirebaseAuth.instance;
  final _emailController = TextEditingController();
  final _passwordController = TextEditingController();
  bool _isLoading = false;
  bool _isLogin = true; // true: 로그인, false: 회원가입

  Future<void> _submit() async {
    final email = _emailController.text.trim();
    final password = _passwordController.text.trim();

    if (email.isEmpty || password.isEmpty) {
      _showError('이메일과 비밀번호를 입력하세요.');
      return;
    }

    setState(() => _isLoading = true);

    try {
      if (_isLogin) {
        await _auth.signInWithEmailAndPassword(
          email: email,
          password: password,
        );
      } else {
        await _auth.createUserWithEmailAndPassword(
          email: email,
          password: password,
        );
      }
    } on FirebaseAuthException catch (e) {
      _showError(_getErrorMessage(e.code));
    } finally {
      setState(() => _isLoading = false);
    }
  }

  String _getErrorMessage(String code) {
    switch (code) {
      case 'email-already-in-use':
        return '이미 사용 중인 이메일입니다.';
      case 'invalid-email':
        return '유효하지 않은 이메일입니다.';
      case 'weak-password':
        return '비밀번호가 너무 약합니다.';
      case 'user-not-found':
        return '등록되지 않은 이메일입니다.';
      case 'wrong-password':
        return '비밀번호가 일치하지 않습니다.';
      default:
        return '오류가 발생했습니다.';
    }
  }

  void _showError(String message) {
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(content: Text(message), backgroundColor: Colors.red),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(_isLogin ? '로그인' : '회원가입')),
      body: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            TextField(
              controller: _emailController,
              decoration: const InputDecoration(
                labelText: '이메일',
                prefixIcon: Icon(Icons.email),
              ),
              keyboardType: TextInputType.emailAddress,
            ),
            const SizedBox(height: 16),
            TextField(
              controller: _passwordController,
              decoration: const InputDecoration(
                labelText: '비밀번호',
                prefixIcon: Icon(Icons.lock),
              ),
              obscureText: true,
            ),
            const SizedBox(height: 24),
            SizedBox(
              width: double.infinity,
              height: 48,
              child: ElevatedButton(
                onPressed: _isLoading ? null : _submit,
                child: _isLoading
                    ? const CircularProgressIndicator(color: Colors.white)
                    : Text(_isLogin ? '로그인' : '회원가입'),
              ),
            ),
            const SizedBox(height: 16),
            TextButton(
              onPressed: () => setState(() => _isLogin = !_isLogin),
              child: Text(_isLogin ? '계정이 없으신가요? 회원가입' : '이미 계정이 있으신가요? 로그인'),
            ),
          ],
        ),
      ),
    );
  }
}

// 홈 화면
class HomeScreen extends StatelessWidget {
  final User user;

  const HomeScreen({super.key, required this.user});

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('홈'),
        actions: [
          IconButton(
            icon: const Icon(Icons.logout),
            onPressed: () => FirebaseAuth.instance.signOut(),
          ),
        ],
      ),
      body: Center(
        child: Column(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            CircleAvatar(
              radius: 50,
              backgroundImage: user.photoURL != null
                  ? NetworkImage(user.photoURL!)
                  : null,
              child: user.photoURL == null
                  ? const Icon(Icons.person, size: 50)
                  : null,
            ),
            const SizedBox(height: 16),
            Text(
              user.displayName ?? user.email ?? 'Unknown',
              style: const TextStyle(fontSize: 24),
            ),
            const SizedBox(height: 8),
            Text(user.email ?? ''),
            if (!user.emailVerified) ...[
              const SizedBox(height: 16),
              ElevatedButton(
                onPressed: () => user.sendEmailVerification(),
                child: const Text('이메일 인증하기'),
              ),
            ],
          ],
        ),
      ),
    );
  }
}
